<template>
	<view v-show='pageShow'>
		<view class="head">
			<navbar :title="'数据统计'" :leftIconColor="'#fff'" :titleStyle='{color:"#fff"}'></navbar>

			<view class="head_card">
				<view class="color-3d f-size-32 f-600">
					累计金额
				</view>
				<view class="color-3d f-size-50 f-600 mt-16 mb-16">
					{{int.totalAmount}}
				</view>
				<view class="color-9 f-size-24 mb-10">
					数据截止{{todayTime}}
				</view>
				<view class="color-9 f-size-24">
					每月公司清算一次
				</view>
			</view>
			<!-- 	<view class="flexc tag_box">
				<view class="tag_item">
					月账单
				</view>
				<view class="tag_item">
					年账单
				</view>
			</view> -->

			<view class="box_1 pl-30">
				<view class="">
					<view class="color-3d f-600 f-size-34 mb-10">
						金额/月
					</view>
					<view class="color-3d f-size-28">
						{{int.mouthConsumeCount || 0}}
					</view>
				</view>
			</view>
		</view>

		<view class="mt-20">
			<uni-calendar class="uni-calendar--hook" :selected="info.selected" :showMonth="false"
				@monthSwitch="monthSwitch" />
		</view>

	</view>
</template>

<script>
	/**
	 * 获取任意时间
	 */
	function getDate(date, AddDayCount = 0) {
		if (!date) {
			date = new Date()
		}
		if (typeof date !== 'object') {
			date = date.replace(/-/g, '/')
		}
		const dd = new Date(date)

		dd.setDate(dd.getDate() + AddDayCount) // 获取AddDayCount天后的日期

		const y = dd.getFullYear()
		const m = dd.getMonth() + 1 < 10 ? '0' + (dd.getMonth() + 1) : dd.getMonth() + 1 // 获取当前月份的日期，不足10补0
		const d = dd.getDate() < 10 ? '0' + dd.getDate() : dd.getDate() // 获取当前几号，不足10补0
		return {
			fullDate: y + '-' + m + '-' + d,
			year: y,
			month: m,
			date: d,
			day: dd.getDay()
		}
	}
	export default {
		components: {},
		data() {
			return {
				showCalendar: false,
				info: {
					lunar: true,
					range: true,
					insert: false,
					selected: []
				},
				todayTime: '',
				int: {},
				pageShow: false
			}
		},
		onLoad() {
			this.statisticsApi()
			this.$nextTick(() => {
				this.showCalendar = true
			})
		},
		methods: {
			async statisticsApi() {
				this.todayTime = getDate(new Date()).fullDate
				let res = await this.statistics()
				if (res.code == 1) {
					this.int = res.data
					res.data.statisticsData.forEach(item => {
						if (item.amount > 0) {
							this.info.selected.push({
								date: item.date,
								info: item.amount
							})
						}
					})
					this.pageShow = true
				}
			},
			open() {
				this.$refs.calendar.open()
			},
			close() {
				console.log('弹窗关闭');
			},
			change(e) {
				console.log('change 返回:', e)
				// 模拟动态打卡
				if (this.info.selected.length > 5) return
				this.info.selected.push({
					date: e.fulldate,
					info: '打卡'
				})
			},
			confirm(e) {
				console.log('confirm 返回:', e)
			},
			monthSwitch(e) {
				console.log('monthSwitchs 返回:', e)
			}
		}
	}
</script>


<style lang="scss">
	page {
		background: #FFFFFF;
	}

	.head {
		width: 100vw;
		height: 560rpx;
		background: linear-gradient(180deg, #0CB080 0%, #fff 100%);

		.head_card {
			width: 699rpx;
			background: #FFFFFF;
			border-radius: 18rpx 18rpx 18rpx 18rpx;
			margin: 10rpx auto 20rpx;
			padding: 30rpx 44rpx;
			box-sizing: border-box;
		}

		.tag_box {
			padding: 14rpx 30rpx;
			box-sizing: border-box;

			.tag_item {
				width: 158rpx;
				height: 69rpx;
				background: #E4E4E4;
				border-radius: 18rpx 18rpx 18rpx 18rpx;
				text-align: center;
				line-height: 69rpx;
				font-size: 24rpx;
				color: #999999;
				line-height: 69rpx;
				text-align: center;
				margin-right: 30rpx;
			}
		}
	}
</style>